INSERT INTO "Exercises" ("ExerciseId", "Name", "Sets", "Reps", "DurationMinutes", "Description", "DescriptionAr", "Difficulty", "Category", "VideoUrl", "CreatedAt", "UpdatedAt", "IsDeleted")
VALUES
  ('039657ab-7351-5f78-a4b8-adcc33d885b2', 'Pelvic Tilting – Standing', 3, 10, 10, 'Stand upright with your feet shoulder-width apart and knees slightly bent. Keep your core gently engaged and place your hands on your hips or a stable support. Gently tilt your pelvis backward to flatten your lower back. Hold the tilted position for 3–5 seconds. Return to the neutral position, relax, and repeat.', 'قف بشكل مستقيم مع وضع القدمين بعرض الكتفين والركبتين مثنيتين قليلاً. حافظ على شد عضلات البطن بلطف، وضع يديك على الحوض أو على دعامة ثابتة. أمل الحوض بلطف إلى الخلف لتسطيح أسفل الظهر. ثبّت وضع الحوض لمدة 3–5 ثوانٍ. عد إلى الوضع المحايد، استرخِ، وكرر التمرين.', 1, 5, '/videos/039657ab-7351-5f78-a4b8-adcc33d885b2.mp4', now(), now(), false),
  ('dbb26a75-a174-5f4c-91c5-e7fb94444e41', 'Prone T Extension', 3, 10, 10, 'Lie face down with arms extended straight out to the sides. Keep the forehead resting on the mat. Squeeze the shoulder blades and lift both arms and neck off the floor. Hold at the top for 2–3 seconds. Lower slowly and repeat.', 'استلقِ على البطن الذراعان ممدودتان للجانبين. اترك الجبهة تستريح على السجادة. اضغط لوحي الكتف و رفع الذراعين والرقبة عن الأرض. ثبّت في الأعلى لمدة 2–3 ثوانٍ. انزل ببطء وكرر.', 1, 0, '/videos/dbb26a75-a174-5f4c-91c5-e7fb94444e41.mp4', now(), now(), false),
  ('950e9a1e-2def-5f18-b666-6b8f4dbaa071', 'Prone Leg Extension', 3, 10, 10, 'Lie face down with legs straight and arms relaxed. Tighten your glutes and lower back. Lift one leg straight up off the floor. Hold at the top for 2–3 seconds. Lower slowly and repeat, then switch legs.', 'استلقِ على البطن والساقين مستقيمتان والذراعين مرتخيتان. اشدّ عضلات الأرداف وأسفل الظهر. ارفع ساقاً واحدة مستقيمة عن الأرض. ثبّت في الأعلى لمدة 2–3 ثوانٍ. انزل ببطء وكرر ثم بدّل الساقين.', 1, 3, '/videos/950e9a1e-2def-5f18-b666-6b8f4dbaa071.mp4', now(), now(), false),
  ('b4672c7a-5900-595b-abea-7ecee4320adc', 'Prone Rows', 3, 10, 10, 'Lie face down on a bench holding a light weight in each hand. Let the arms hang straight toward the floor. Pull the elbows up toward the ribs, squeezing shoulder blades. Pause briefly at the top. Lower slowly and repeat.', 'استلقِ على البطن على مقعد ووزن خفيف بكل يد. اترك الذراعين متدليتين نحو الأرض. اسحب الكوعين نحو الأضلاع مع ضغط لوحي الكتف. توقف لحظة في الأعلى. انزل ببطء وكرر.', 1, 0, '/videos/b4672c7a-5900-595b-abea-7ecee4320adc.mp4', now(), now(), false),
  ('a26cd63e-cb8a-5962-b42b-29c21ec532c6', 'Prone Shoulder Extension', 3, 10, 10, 'Lie face down with arms straight at your sides. Keep the forehead resting on the mat. Lift both arms back and up toward the ceiling. Squeeze the shoulder blades together. Hold briefly and lower with control.', 'استلقِ على البطن والذراعين مستقيمتان بجانب الجسم. اترك الجبهة على السجادة. ارفع الذراعين للخلف وللأعلى نحو السقف. اضغط لوحي الكتف معاً. ثبّت لحظة ثم أنزل بتحكم.', 1, 0, '/videos/a26cd63e-cb8a-5962-b42b-29c21ec532c6.mp4', now(), now(), false),
  ('ba49a8d4-d5a6-51a8-8b06-e4d09cbcb487', 'Push-Ups', 3, 10, 10, 'Start in a plank with hands under shoulders. Keep the body straight from head to heels. Bend the elbows and lower the chest toward the floor. Push back up until the arms are straight. Repeat with a steady tempo.', 'ابدأ بوضع البلانك واليدان تحت الكتفين. حافظ على استقامة الجسم من الرأس إلى الكعبين. اثنِ الكوعين وأنزل الصدر نحو الأرض. ادفع للأعلى حتى تستقيم الذراعان. كرر بإيقاع ثابت.', 2, 3, '/videos/ba49a8d4-d5a6-51a8-8b06-e4d09cbcb487.mp4', now(), now(), false),
  ('d4078953-7e82-5a66-b5c6-e626558bf2cc', 'Quadruped Knee Raises', 3, 10, 10, 'Start on all fours with hands under shoulders. Keep the back flat and core engaged. Lift both knees just off the floor. Hold the hovering position for 10–15 seconds. Lower slowly and repeat.', 'ابدأ على اليدين والركبتين واليدان تحت الكتفين. حافظ على ظهر مستقيم وشد عضلات البطن. رفع الركبتين قليلاً عن الأرض. ثبّت وضع التعليق لمدة 15–10 ثوانٍ. انزل ببطء وكرر.', 1, 6, '/videos/d4078953-7e82-5a66-b5c6-e626558bf2cc.mp4', now(), now(), false),
  ('a6a7f13d-7f16-5997-be0a-ad4158427d7c', 'Quadruped Serratus Punch', 3, 10, 10, 'Start on all fours with hands under shoulders. Keep the arms straight and back flat. Push the floor away, rounding the upper back. Feel the shoulder blades spread apart. Return to neutral and repeat.', 'ابدأ على اليدين والركبتين واليدان تحت الكتفين. حافظ على استقامة الذراعين و استواء الظهر. ادفع الأرض بعيداً مع تقويس أعلى الظهر. أشعر بابتعاد لوحي الكتف عن بعضهما. عد للوضع المحايد وكرر.', 1, 0, '/videos/a6a7f13d-7f16-5997-be0a-ad4158427d7c.mp4', now(), now(), false),
  ('453ad2a9-787f-5231-900d-dac8dfe46b33', 'Resisted Forearm Supination and Pronation', 3, 10, 10, 'Sit with the elbow bent at 90 degrees at your side. Hold a resistance band handle in your hand. Rotate the palm upward against the band, then downward. Keep the elbow tucked to the body. Move slowly through the full range.', 'اجلس مع ثني الكوع 90 درجة بجانب الجسم. أمسك مقبض شريط المقاومة باليد. أدر راحة اليد للأعلى ضد الشريط ثم للأسفل. حافظ على تثبيت الكوع بجانب الجسم. تحرك ببطء عبر النطاق الكامل.', 1, 2, '/videos/453ad2a9-787f-5231-900d-dac8dfe46b33.mp4', now(), now(), false),
  ('3b5d781c-915a-5037-b0a1-6ecf60e897f2', 'Resisted Forearm Supination', 3, 10, 10, 'Sit with the elbow bent at 90 degrees, palm facing down. Hold a resistance band anchored at the side. Rotate the palm upward against the band''s pull. Hold at the top position briefly. Return slowly and repeat.', 'اجلس مع ثني الكوع 90 درجة وراحة اليد للأسفل. أمسك شريط مقاومة مثبت من الجانب. أدر راحة اليد للأعلى ضد شد الشريط. ثبّت في الأعلى لحظة. عد ببطء وكرر.', 1, 2, '/videos/3b5d781c-915a-5037-b0a1-6ecf60e897f2.mp4', now(), now(), false),
  ('74b091ff-0cf8-5edb-832e-f95c615a9818', 'Resisted Radial Deviation', 3, 10, 10, 'Sit with the forearm supported on a table, thumb up. Hold a resistance band anchored below the hand. Bend the wrist upward toward the thumb side. Hold at the top for 5–10 seconds. Return slowly and repeat.', 'اجلس والساعد مستند على طاولة والإبهام للأعلى. أمسك شريط مقاومة مثبت تحت اليد. اثنِ الرسغ للأعلى نحو جهة الإبهام. ثبّت في الأعلى لمدة 2–3 ثوانٍ. عد ببطء وكرر.', 1, 2, '/videos/74b091ff-0cf8-5edb-832e-f95c615a9818.mp4', now(), now(), false),
  ('ca295aa5-e701-5322-9210-ce8fa0a3bc2f', 'Resisted Shoulder Abduction', 3, 10, 10, 'Stand on a resistance band with feet shoulder-width apart. Hold the band handle at your side, arm straight. Raise the arm out to the side to shoulder height. Keep the elbow straight throughout. Lower slowly with control and repeat.', 'قف على شريط مقاومة والقدمان بعرض الكتفين. أمسك مقبض الشريط بجانب الجسم والذراع مستقيمة. ارفع الذراع للجانب حتى مستوى الكتف. حافظ على استقامة الكوع طول الحركة. انزل ببطء بتحكم وكرر.', 1, 0, '/videos/ca295aa5-e701-5322-9210-ce8fa0a3bc2f.mp4', now(), now(), false),
  ('8c8a08dd-39c0-5239-aeac-54c3afa4be16', 'Resisted Ulnar Deviation', 3, 10, 10, 'Sit with the forearm on a table, thumb up. Hold a resistance band anchored above the hand. Bend the wrist downward toward the pinky side. Hold at the end range for 5–10 seconds. Return slowly and repeat.', 'اجلس والساعد على طاولة والإبهام للأعلى. أمسك شريط مقاومة مثبت فوق اليد. اثنِ الرسغ للأسفل نحو جهة الخنصر. ثبّت في نهاية الحركة لمدة 5–10 ثوانٍ. عد ببطء وكرر.', 1, 2, '/videos/8c8a08dd-39c0-5239-aeac-54c3afa4be16.mp4', now(), now(), false),
  ('182471db-d6fe-559a-83a1-2f2523c39919', 'Resisted Wrist Extension', 3, 10, 10, 'Sit with the forearm on a table, palm facing down. Hold a resistance band anchored under the foot. Lift the hand upward against the band''s pull. Hold at the top for 10–5 seconds. Lower slowly and repeat.', 'اجلس والساعد على طاولة وراحة اليد للأسفل. أمسك شريط مقاومة مثبت تحت القدم. ارفع اليد للأعلى ضد شد الشريط. ثبّت في الأعلى لمدة 5-10 ثوانٍ. انزل ببطء وكرر.', 1, 2, '/videos/182471db-d6fe-559a-83a1-2f2523c39919.mp4', now(), now(), false),
  ('419e6e03-ec0f-595d-b987-15440bce0ba3', 'Resisted Wrist Flexion', 3, 10, 10, 'Sit with the forearm on a table, palm facing up. Hold a resistance band anchored under the foot. Curl the hand upward against the band''s pull. Hold at the top for 10–15 seconds. Lower slowly and repeat.', 'اجلس والساعد على طاولة وراحة اليد للأعلى. أمسك شريط مقاومة مثبت تحت القدم. لفّ اليد للأعلى ضد شد الشريط. ثبّت في الأعلى لمدة 10–15 ثوانٍ. انزل ببطء وكرر.', 1, 2, '/videos/419e6e03-ec0f-595d-b987-15440bce0ba3.mp4', now(), now(), false),
  ('6374fadb-a43e-5eb9-bae9-c9b3b240f264', 'Scapular Squeeze', 3, 10, 10, 'Stand or sit upright with arms relaxed at your sides. Keep the chest lifted and shoulders down. Squeeze the shoulder blades together toward the spine. Hold the squeeze for 10-20 seconds. Release slowly and repeat.', 'قف أو اجلس بشكل مستقيم والذراعين مسترخيتان. حافظ على رفع الصدر وإنزال الكتفين. اضغط لوحي الكتف معاً نحو العمود الفقري. ثبّت الضغطة لمدة 10-20 ثوانٍ. استرخِ ببطء وكرر.', 1, 0, '/videos/6374fadb-a43e-5eb9-bae9-c9b3b240f264.mp4', now(), now(), false),
  ('63735d4a-9d76-574f-a3e7-7214a545d868', 'Scorpion', 3, 10, 10, 'Lie face down with arms extended out to the sides. Lift one leg and cross it over the opposite side of the body. Try to touch the foot to the floor on the far side. Keep the shoulders as flat as possible. Return slowly and switch sides.', 'استلقِ على البطن الذراعان ممدودتان للجانبين. ارفع ساقاً واحدة وضعها فوق الجسم للجهة المعاكسة. حاول لمس القدم للأرض على الجهة البعيدة. حافظ على الكتفين مسطحين قدر الإمكان. عد ببطء وبدّل الجانبين.', 2, 4, '/videos/63735d4a-9d76-574f-a3e7-7214a545d868.mp4', now(), now(), false),
  ('5aeecb47-bc67-563d-a491-65e7c6c5fadd', 'Seated Back Extension', 3, 10, 10, 'Sit upright in a chair with feet flat on the floor. Place your hands lightly behind your head. Slowly arch the upper back and look upward. Feel the chest open at the end range. Return to upright and repeat.', 'اجلس بشكل مستقيم في كرسي والقدمان على الأرض. ضع اليدين بلطف خلف الرأس. قوّس أعلى الظهر ببطء وانظر للأعلى. أشعر بانفتاح الصدر في نهاية الحركة. عد للوضع المستقيم وكرر.', 0, 3, '/videos/5aeecb47-bc67-563d-a491-65e7c6c5fadd.mp4', now(), now(), false),
  ('08aee01f-aecd-5d69-8905-d843d2abefa8', 'Seated Biceps Stretch', 3, 10, 10, 'Sit with your legs straight in front. Place your hands behind you, palms flat. Point your fingers away from your body. Slowly move your hips forward until you feel the stretch. Hold for 15–20 seconds, then relax.', 'اجلس ومدّ ساقيك أمامك. ضع يديك خلفك، والراحتين على الأرض. وجّه أصابعك بعيدًا عن جسمك. حرّك الوركين للأمام ببطء حتى تشعر بالتمدد. ثبّت 15–20 ثانية، ثم استرخِ.', 0, 1, '/videos/08aee01f-aecd-5d69-8905-d843d2abefa8.mp4', now(), now(), false),
  ('b8183e27-3749-537e-91c7-7a932fff9c01', 'Seated Elbow Extension Slide with Towel', 3, 10, 10, 'Sit at a table with a small towel under your hand. Place the elbow bent at 90 degrees. Slide the hand forward on the towel, straightening the elbow. Reach as far as comfortable. Slide back to start and repeat.', 'اجلس عند طاولة ومنشفة صغيرة تحت اليد. ضع الكوع مثنياً 90 درجة. اسحب اليد للأمام على المنشفة مع فرد الكوع. امتد لأقصى مسافة مريحة. ارجع للبداية وكرر.', 0, 1, '/videos/b8183e27-3749-537e-91c7-7a932fff9c01.mp4', now(), now(), false),
  ('008a1640-5ba9-52a0-b9b8-d1066e32fe18', 'Seated Lumbar Rotation', 3, 10, 10, 'Sit upright in a chair with feet flat on the floor. Cross the arms over the chest. Slowly rotate the trunk to one side as far as comfortable. Hold at the end range for 5–10 seconds. Return to center and rotate to the other side.', 'اجلس بشكل مستقيم في كرسي والقدمان على الأرض. شبّك الذراعين على الصدر. أدر الجذع ببطء لجهة قدر ما تسمح الراحة. ثبّت في نهاية الحركة لمدة 5–10 ثوانٍ. عد للوسط وأدر للجهة الأخرى.', 0, 3, '/videos/008a1640-5ba9-52a0-b9b8-d1066e32fe18.mp4', now(), now(), false),
  ('ca164a76-8196-5d49-936b-fa7085215cdc', 'Seated Neck Flexion', 3, 10, 10, 'Sit upright with shoulders relaxed. Slowly lower the chin toward the chest. Feel a stretch along the back of the neck. Hold 10–15 seconds while breathing calmly. Lift the head slowly back to neutral.', 'اجلس بشكل مستقيم مع استرخاء الكتفين. أنزل الذقن ببطء نحو الصدر. اشعر بالشد على خلفية الرقبة. ثبّت 10–15 ثانية مع التنفس الهادئ. ارفع الرأس ببطء للوضع المحايد.', 0, 3, '/videos/ca164a76-8196-5d49-936b-fa7085215cdc.mp4', now(), now(), false),
  ('d38b2b2a-4f4f-5d81-9c2a-f354f60f20c5', 'Seated Piriformis Stretch', 3, 10, 10, 'Sit upright in a chair with feet flat on the floor. Cross one ankle over the opposite knee. Keep the back straight and lean gently forward. Feel the stretch deep in the buttock. Hold 20–30 seconds then switch sides.', 'اجلس بشكل مستقيم في كرسي والقدمان على الأرض. ضع كاحل قدم على الركبة المعاكسة. حافظ على استقامة الظهر وانحنِ للأمام بلطف. اشعر بالشد العميق في الأرداف. ثبّت 20–30 ثانية ثم بدّل.', 0, 5, '/videos/d38b2b2a-4f4f-5d81-9c2a-f354f60f20c5.mp4', now(), now(), false),
  ('f8db7073-016d-52d2-9c8b-9c404c2e2ddb', 'Seated Stretch', 3, 10, 10, 'Sit upright  with feet flat on the floor. Interlock the fingers and press palms outward. Raise both arms overhead as high as comfortable. Feel a full-body stretch through the sides. Hold 15–20 seconds and lower slowly.', 'اجلس بشكل مستقيم والقدمين على الأرض. شبّك الأصابع واضغط راحتي اليدين للخارج. ارفع الذراعين فوق الرأس لأعلى ارتفاع مريح. اشعر بشد كامل عبر جانبي الجسم. ثبّت 15–20 ثانية وأنزل ببطء.', 0, 3, '/videos/f8db7073-016d-52d2-9c8b-9c404c2e2ddb.mp4', now(), now(), false),
  ('e1c30b39-4ed4-5baf-ba2f-66492a44dd6e', 'Seated Thoracic Twist', 3, 10, 10, 'Sit upright in a chair with feet flat on the floor. Place one hand on the opposite knee. Rotate the trunk toward the placed hand. Look over the shoulder in the direction of the twist. Hold 15–20 seconds and switch sides.', 'اجلس بشكل مستقيم في كرسي والقدمان على الأرض. ضع يداً على الركبة المعاكسة. أدر الجذع باتجاه اليد الموضوعة. انظر فوق الكتف في اتجاه اللف. ثبّت 15–20 ثانية وبدّل.', 0, 3, '/videos/e1c30b39-4ed4-5baf-ba2f-66492a44dd6e.mp4', now(), now(), false),
  ('f4753242-7791-5777-ac12-6072502e02bf', 'Seated Toe Touch', 3, 10, 10, 'Sit on the floor with legs straight in front. Keep the back tall and toes flexed upward. Slowly hinge forward from the hips. Reach the hands toward the toes. Hold 20–30 seconds then sit back up.', 'اجلس على الأرض والساقين مستقيمتان أمامك. حافظ على استقامة الظهر وثني أصابع القدمين للأعلى. انحنِ للأمام ببطء من الوركين. مدّ اليدين نحو أصابع القدمين. ثبّت 20–30 ثانية ثم عاد للجلوس.', 0, 7, '/videos/f4753242-7791-5777-ac12-6072502e02bf.mp4', now(), now(), false),
  ('82780402-56b3-5efb-a90e-065cb6484c80', 'Seated Towel Grabbing', 3, 10, 10, 'Sit with feet flat on a towel spread on the floor. Curl the toes to gather the towel underneath. Continue until the towel is fully bunched. Release and flatten the towel again. Repeat with each foot.', 'اجلس والقدمان على منشفة مفرودة على الأرض. لفّ أصابع القدم لتجميع المنشفة تحتها. تابع حتى تتجمع المنشفة بالكامل. استرخِ وأعد فرد المنشفة. كرر بكل قدم.', 0, 2, '/videos/82780402-56b3-5efb-a90e-065cb6484c80.mp4', now(), now(), false),
  ('b9c07967-2ba0-5426-b503-3b6455944de3', 'Serratus Punch Resisted', 3, 10, 10, 'Lie on your back holding a resistance band overhead. Anchor the band under the shoulders. Punch the arms straight up toward the ceiling. Feel the shoulder blades spread apart at the top. Return slowly and repeat.', 'استلقِ على ظهرك ممسكاً بشريط مقاومة فوق الرأس. ثبّت الشريط تحت الكتفين. ادفع الذراعين مستقيمتين للأعلى نحو السقف. أشعر بابتعاد لوحي الكتف في الأعلى. عد ببطء وكرر.', 1, 0, '/videos/b9c07967-2ba0-5426-b503-3b6455944de3.mp4', now(), now(), false),
  ('0d118c3a-761a-5987-a2bf-43d3b50a4b11', 'Serratus Punch', 3, 10, 10, 'Lie on your back holding a light weight in each hand. Extend the arms straight up above the shoulders. Push the weights higher by lifting the shoulder blades off the floor. Hold at the top for 2 seconds. Lower slowly and repeat.', 'استلقِ على ظهرك ووزن خفيف بكل يد. فرد الذراعين مستقيمين فوق الكتفين. ادفع الأوزان أعلى برفع لوحي الكتف عن الأرض. ثبّت في الأعلى لمدة ثانيتين. انزل ببطء وكرر.', 1, 0, '/videos/0d118c3a-761a-5987-a2bf-43d3b50a4b11.mp4', now(), now(), false),
  ('53b9e5d4-79ab-567d-acc6-dc076330a622', 'Shoulder Internal Rotation Band Resisted', 3, 10, 10, 'Stand next to a resistance band anchored at elbow height. Bend the elbow 90 degrees and hold the handle. Rotate the forearm across the body against resistance. Keep the elbow tucked to your side. Return slowly and repeat.', 'قف بجانب شريط مقاومة مثبت عند مستوى الكوع. اثنِ الكوع 90 درجة و أمسك المقبض. أدر الساعد عبر الجسم ضد المقاومة. حافظ على تثبيت الكوع بجانب الجسم. عد ببطء وكرر.', 1, 0, '/videos/53b9e5d4-79ab-567d-acc6-dc076330a622.mp4', now(), now(), false),
  ('e581adb1-2738-59be-aa47-cf4ddc098e28', 'Shoulder Circumduction', 3, 10, 10, 'Stand and bend forward at the hips slightly. Let one arm hang straight toward the floor. Make small slow circles with the hand. Gradually widen the circles as tolerated. Reverse direction and repeat.', 'قف وانحنِ قليلاً من الوركين. اترك ذراعاً واحدة متدلية نحو الأرض. ارسم دوائر صغيرة بطيئة باليد. وسّع الدوائر تدريجياً حسب التحمل. اعكس الاتجاه وكرر.', 0, 0, '/videos/e581adb1-2738-59be-aa47-cf4ddc098e28.mp4', now(), now(), false),
  ('2e55d6e5-a98e-5c7c-8434-61a4a36aa44e', 'Shoulder Clock Resisted', 3, 10, 10, 'Stand facing a wall with a resistance band anchored in front. Hold the handle with the affected arm. Move the arm around a clock face — 12, 3, 6, 9 positions. Keep the movement slow and controlled. Complete a full clockwise cycle then reverse.', 'قف مواجهاً حائطاً وشريط مقاومة مثبت أمامك. أمسك المقبض الذراع المصابة. حرّك الذراع حول ساعة — أوضاع 12، 3، 6، 9. حافظ على حركة بطيئة ومتحكم بها. أكمل دورة كاملة باتجاه عقارب الساعة ثم اعكس.', 1, 0, '/videos/2e55d6e5-a98e-5c7c-8434-61a4a36aa44e.mp4', now(), now(), false),
  ('f9e459bf-fd4e-569f-ac38-a9ae4e3001c9', 'Shoulder External Rotation Band Resisted', 3, 10, 10, 'Stand next to a resistance band anchored at elbow height. Bend the elbow 90 degrees, palm facing inward. Rotate the forearm outward against the band. Keep the elbow tucked to your side. Return slowly and repeat.', 'قف بجانب شريط مقاومة مثبت عند مستوى الكوع. اثنِ الكوع 90 درجة وراحة اليد للداخل. أدر الساعد للخارج ضد الشريط. حافظ على تثبيت الكوع بجانب الجسم. عد ببطء وكرر.', 1, 0, '/videos/f9e459bf-fd4e-569f-ac38-a9ae4e3001c9.mp4', now(), now(), false),
  ('3072672e-4be5-5099-8689-9ce07c0abfdc', 'Shoulder External Rotation with Stick', 3, 10, 10, 'Stand or sit holding a stick with both hands. Bend both elbows to 90 degrees at your sides. Use the healthy arm to push the stick outward. Guide the affected arm into external rotation. Return slowly and repeat.', 'قف أو اجلس ممسكاً بعصا بكلتا اليدين. اثنِ الكوعين 90 درجة بجانب الجسم. استخدم الذراع السليمة لدفع العصا للخارج. وجّه الذراع المصابة للدوران للخارج. عد ببطء وكرر.', 1, 0, '/videos/3072672e-4be5-5099-8689-9ce07c0abfdc.mp4', now(), now(), false),
  ('a0e944b5-b29f-5f83-acfc-c61ac8c89e61', 'Shoulder Internal Rotation Passive', 3, 10, 10, 'Sit or stand and place the non-affected hand will grab the affected hand. Use the other hand to gently pull the wrist to the middle side. Help the affected hand to reach the middle as much as you can. Feel the rotation across the front of the shoulder. Hold 15–20 seconds and release.', 'اجلس أو قف وضع اليد غير المتأثرة لتُمسك باليد المتأثرة. استخدم اليد الأخرى لسحب الرسغ بلطف نحو الجانب الأوسط. ساعد اليد المتأثرة على الوصول إلى المنتصف قدر الإمكان. اشعر بالدوران عبر الجزء الأمامي من الكتف. ثبّت لمدة 15–20 ثانية ثم حرّر.', 0, 0, '/videos/a0e944b5-b29f-5f83-acfc-c61ac8c89e61.mp4', now(), now(), false),
  ('f2dab272-2516-5be1-88af-eef9305779aa', 'Shoulder Internal Rotation with Stick', 3, 10, 10, 'Stand or sit holding a stick with both hands. Grip the stick with the affected hand at the bottom. Use the top hand to pull the stick upward. Guide the bottom arm into internal rotation. Hold 5 seconds and return slowly.', 'قف أو اجلس ممسكاً بعصا بكلتا اليدين. أمسك العصا باليد المصابة من الأسفل. استخدم اليد العلوية سحب العصا للأعلى. وجّه الذراع السفلى للدوران للداخل. ثبّت 5 ثوانٍ وعد ببطء.', 1, 0, '/videos/f2dab272-2516-5be1-88af-eef9305779aa.mp4', now(), now(), false),
  ('1a927cba-10df-534b-be00-5ad6225dbc95', 'Shoulder Rolls', 3, 10, 10, 'Stand or sit upright with arms relaxed at your sides. Lift both shoulders up toward the ears. Roll them backward and downward in a smooth circle. Complete rolls one direction. Reverse direction and repeat.', 'قف أو اجلس بشكل مستقيم والذراعين مسترخيتان. ارفع الكتفين للأعلى نحو الأذنين. لفّهما للخلف والأسفل بحركة دائرية سلسلة. أكمل 5–10 دورات باتجاه واحد. اعكس الاتجاه وكرر.', 0, 0, '/videos/1a927cba-10df-534b-be00-5ad6225dbc95.mp4', now(), now(), false),
  ('8cfa9d15-7bf9-59e8-8194-404f62adf352', 'Shoulder Shrugs', 3, 10, 10, 'Stand upright with arms relaxed at your sides. Lift both shoulders straight up toward the ears. Hold the top position for 10–20 seconds. Lower slowly with control. Repeat for the prescribed reps.', 'قف بشكل مستقيم والذراعين مرتخيتان. ارفع الكتفين مستقيماً للأعلى نحو الأذنين. ثبّت في الأعلى لمدة 10–20 ثوانٍ. انزل ببطء بتحكم. كرر للعدد المطلوب.', 0, 0, '/videos/8cfa9d15-7bf9-59e8-8194-404f62adf352.mp4', now(), now(), false),
  ('37a81bc3-6e7f-559e-a6cc-721df736a02d', 'Side Lying Hip Abduction', 3, 10, 10, 'Lie on your side with legs stacked and straight. Support the head with your bottom arm. Lift the top leg straight up toward the ceiling. Keep the toes pointing forward, not up. Lower slowly and repeat, then switch sides.', 'استلقِ على جانبك و الساقين مستقيمتين فوق بعضهما. ادعم الرأس الذراع السفلى. ارفع الساق العلوية مستقيمة نحو السقف. حافظ على توجيه الأصابع للأمام لا للأعلى. انزل ببطء وكرر ثم بدّل.', 1, 5, '/videos/37a81bc3-6e7f-559e-a6cc-721df736a02d.mp4', now(), now(), false),
  ('202aa2b2-4889-5e70-a268-b77667a79f22', 'Side Lying Hip Flexor Stretch', 3, 10, 10, 'Lie on your side with the bottom leg bent forward. Grab the top ankle and pull it toward your buttock. Push the hip slightly forward for a deeper stretch. Feel a stretch across the front of the hip and thigh. Hold 20–30 seconds then switch sides.', 'استلقِ على جانبك و الساق السفلية مثنية للأمام. أمسك كاحل الساق العلوية واسحبه نحو الأرداف. ادفع الورك للأمام قليلاً لتعميق الشد. اشعر بالشد على مقدمة الورك والفخذ. ثبّت 20–30 ثانية ثم بدّل.', 0, 5, '/videos/202aa2b2-4889-5e70-a268-b77667a79f22.mp4', now(), now(), false),
  ('b0419fe7-fd30-5541-a939-e56db7f346e9', 'Side Lying Passive External Rotation', 3, 10, 10, 'Lie on your side with the affected arm on top. Bend the elbow 90 degrees with your forearm across the belly. Use the other hand to gently rotate the forearm upward. Guide the arm into external rotation. Hold 5–10 seconds then release.', 'استلقِ على جانبك و الذراع المصابة لأعلى. اثنِ الكوع 90 درجة والساعد على البطن. استخدم اليد الأخرى تدوير الساعد للأعلى بلطف. وجّه الذراع للدوران للخارج. ثبّت 5–10 ثوانٍ ثم استرخِ.', 0, 3, '/videos/b0419fe7-fd30-5541-a939-e56db7f346e9.mp4', now(), now(), false),
  ('bfb493cd-1fba-5649-be58-473d0f0c9b57', 'Side Lying Shoulder Flexion', 3, 10, 10, 'Lie on your side with the affected arm on top. Keep the arm straight along the side of the body. Raise the arm forward and up toward the ceiling. Move as far as comfortable without pain. Lower slowly and repeat.', 'استلقِ على جانبك و الذراع المصابة لأعلى. حافظ على استقامة الذراع بجانب الجسم. ارفع الذراع للأمام والأعلى نحو السقف. تحرك لأقصى مدى مريح بدون ألم. انزل ببطء وكرر.', 1, 0, '/videos/bfb493cd-1fba-5649-be58-473d0f0c9b57.mp4', now(), now(), false),
  ('b0372096-25cb-5c21-bbc7-f5ec111f6ff4', 'Side Plank with Hip Abduction', 3, 10, 10, 'Lie on your side propped on the forearm. Lift the hips into a side plank position. Raise the top leg up toward the ceiling. Hold the position for 3–5 seconds. Lower with control and repeat.', 'استلقِ على جانبك مستنداً على الساعد. رفع الوركين لوضع البلانك الجانبي. ارفع الساق العلوية للأعلى نحو السقف. ثبّت الوضع لمدة 3–5 ثوانٍ. أنزل بتحكم وكرر.', 2, 5, '/videos/b0372096-25cb-5c21-bbc7-f5ec111f6ff4.mp4', now(), now(), false),
  ('12c85ff1-15b7-5d36-9d85-9e723f558e3a', 'Side Walking Squats', 3, 10, 10, 'Stand with feet hip-width apart, knees slightly bent. Lower into a quarter squat position. Step sideways with one foot, then follow with the other. Keep the squat position throughout the movement. Continue 8–10 steps then reverse direction.', 'قف والقدمان بعرض الوركين والركبتين مثنيتين قليلاً. انزل إلى وضع سكوات ربع. اخطُ جانبياً بقدم ثم اتبع بالأخرى. حافظ على وضع السكوات طوال الحركة. تابع 8–10 خطوات ثم اعكس الاتجاه.', 2, 6, '/videos/12c85ff1-15b7-5d36-9d85-9e723f558e3a.mp4', now(), now(), false),
  ('b8ed15ab-e957-5ce1-a516-5f8dee62624b', 'Single Leg Bridging', 3, 10, 10, 'Lie on your back with knees bent and feet flat. Straighten one leg pointing toward the ceiling. Push through the planted heel to lift the hips. Hold at the top for 2–3 seconds. Lower slowly and repeat, then switch legs.', 'استلقِ على ظهرك مع ثني الركبتين ووضع القدمين على الأرض. افرد ساقاً واحدة موجهة نحو السقف. ادفع من الكعب المثبت رفع الوركين. ثبّت في الأعلى لمدة 2–3 ثوانٍ. انزل ببطء وكرر ثم بدّل.', 2, 5, '/videos/b8ed15ab-e957-5ce1-a516-5f8dee62624b.mp4', now(), now(), false),
  ('cf3c2ce1-f527-5e99-8faa-559fe42a68d7', 'Single Leg Squat', 3, 10, 10, 'Stand on one leg with the other lifted slightly forward. Extend the arms forward for balance. Slowly bend the standing knee and lower the hips. Go down as far as controlled and safe. Push through the heel to return upright.', 'قف على ساق واحدة والأخرى مرفوعة قليلاً للأمام. مدّ الذراعين للأمام للتوازن. اثنِ ركبة الوقوف ببطء وأنزل الوركين. انزل لأقصى مدى آمن ومتحكم به. ادفع من الكعب للعودة للوقوف.', 2, 6, '/videos/cf3c2ce1-f527-5e99-8faa-559fe42a68d7.mp4', now(), now(), false),
  ('fdfb996b-5104-5c7f-815b-b937979a1b3a', 'Sitting Arm Slide with Towel', 3, 10, 10, 'Sit at a table with a small towel under your hand. Rest the forearm on the table. Slide the hand forward as far as comfortable. Feel a stretch through the shoulder and back. Slide back to start and repeat.', 'اجلس عند طاولة ومنشفة صغيرة تحت اليد. ضع الساعد على الطاولة. اسحب اليد للأمام لأقصى مسافة مريحة. اشعر بالشد في الكتف والظهر. ارجع للبداية وكرر.', 1, 3, '/videos/fdfb996b-5104-5c7f-815b-b937979a1b3a.mp4', now(), now(), false),
  ('43e0f0aa-d337-59ad-bda1-ecdcb070d548', 'Slump Stretch', 3, 10, 10, 'Sit on the edge of a chair with feet flat on the floor. Round the back and drop the chin to the chest. Slowly straighten one knee, flexing the ankle. Feel a stretch through the back of the leg. Hold 15–20 seconds and switch legs.', 'اجلس على حافة كرسي والقدمان على الأرض. قوّس الظهر وأنزل الذقن على الصدر. افرد ركبة واحدة ببطء مع ثني الكاحل. اشعر بالشد على خلفية الساق. ثبّت 15–20 ثانية وبدّل.', 0, 3, '/videos/43e0f0aa-d337-59ad-bda1-ecdcb070d548.mp4', now(), now(), false),
  ('822d8160-62ba-5fd9-a201-fe99d6953dff', 'Spider Walk', 3, 10, 10, 'Start in a plank position with hands under shoulders. Bring one knee toward the same-side elbow. Return the foot back to plank position. Alternate legs with a steady rhythm. Continue for the prescribed reps.', 'ابدأ بوضع البلانك واليدان تحت الكتفين. قرّب ركبة واحدة نحو الكوع من نفس الجهة. عد بالقدم لوضع البلانك. بدّل الساقين بإيقاع ثابت. تابع للعدد المطلوب.', 2, 4, '/videos/822d8160-62ba-5fd9-a201-fe99d6953dff.mp4', now(), now(), false),
  ('7636501d-dc49-5110-87e7-e7dcdc8451a4', 'Split Squats', 3, 10, 10, 'Stand with one foot in front and one behind in a lunge stance. Keep the torso upright and core engaged. Bend both knees to lower the hips straight down. Push through the front heel to return upright. Repeat for the prescribed reps then switch legs.', 'قف بقدم للأمام والأخرى للخلف بوضع الاندفاع. حافظ على استقامة الجذع وشد عضلات البطن. اثنِ الركبتين وأنزل الوركين مباشرة للأسفل. ادفع من كعب القدم الأمامية للعودة للوقوف. كرر للعدد المطلوب ثم بدّل.', 2, 6, '/videos/7636501d-dc49-5110-87e7-e7dcdc8451a4.mp4', now(), now(), false),
  ('9b414239-c7d0-58e5-8c93-05a57dd27978', 'Squats with Overhead Reach', 3, 10, 10, 'Stand with feet shoulder-width apart, arms overhead. Lower into a squat while keeping arms raised. Reach as high as possible at the bottom. Push through the heels to return upright. Keep the arms overhead throughout.', 'قف والقدمان بعرض الكتفين و الذراعين فوق الرأس. انزل بالسكوات مع إبقاء الذراعين مرفوعتين. امتد لأعلى ما يمكن في الأسفل. ادفع من الكعبين للعودة للوقوف. حافظ على الذراعين فوق الرأس طوال الحركة.', 1, 6, '/videos/9b414239-c7d0-58e5-8c93-05a57dd27978.mp4', now(), now(), false),
  ('11aaf049-342d-5456-961d-bb4bbc52ca38', 'Squats', 3, 10, 10, 'Stand with feet shoulder-width apart, toes slightly out. Keep the chest lifted and core engaged. Bend the knees and hips to lower into a squat. Go down until thighs are roughly parallel to the floor. Push through the heels to return upright.', 'قف والقدمان بعرض الكتفين وأصابع القدم للخارج قليلاً. حافظ على رفع الصدر وشد عضلات البطن. اثنِ الركبتين والوركين للنزول بالسكوات. انزل حتى تصبح الفخذين موازيتين للأرض تقريباً. ادفع من الكعبين للعودة للوقوف.', 1, 6, '/videos/11aaf049-342d-5456-961d-bb4bbc52ca38.mp4', now(), now(), false),
  ('02451fa4-344f-5b73-88d7-826488bbe20f', 'Standing Y Raises', 3, 10, 10, 'Stand with feet hip-width apart, arms at your sides. Hinge slightly forward from the hips. Raise both arms out and up in a Y shape. Squeeze the shoulder blades at the top. Lower slowly and repeat.', 'قف والقدمان بعرض الوركين و الذراعان بجانب الجسم. انحنِ قليلاً للأمام من الوركين. ارفع الذراعين للخارج و للأعلى بشكل حرف Y. اضغط لوحي الكتف في الأعلى. انزل ببطء وكرر.', 1, 0, '/videos/02451fa4-344f-5b73-88d7-826488bbe20f.mp4', now(), now(), false),
  ('fc438435-98f5-5129-8f5e-48fceb292a48', 'Standing Adductors Stretch', 3, 10, 10, 'Stand with feet wider than shoulder-width apart. Shift the hips to one side, bending that knee. Keep the other leg straight with toes forward. Feel a stretch through the inner thigh of the straight leg. Hold 20–30 seconds and switch sides.', 'قف والقدمان أوسع من الكتفين. انقل الوركين إلى جهة واحدة مع ثني تلك الركبة. حافظ على استقامة الساق الأخرى وأصابعها للأمام. تشعر بالشد على الفخذ الداخلي الساق المستقيمة. ثبّت 20–30 ثانية وبدّل.', 0, 5, '/videos/fc438435-98f5-5129-8f5e-48fceb292a48.mp4', now(), now(), false),
  ('81d785ab-96f4-5f7d-88ba-48d0db3b85b0', 'Standing Calf Raises', 3, 10, 10, 'Stand tall with feet hip-width apart. Hold onto a wall or chair for balance if needed. Slowly rise up onto the tip-toes of the feet. Hold at the top for 10–20 seconds. Lower slowly and repeat.', 'قف بشكل مستقيم والقدمين بعرض الوركين. أمسك بحائط أو كرسي للتوازن إذا لزم. ارتفع ببطء على أطراف القدمين. ثبّت في الأعلى لمدة 10–15 ثانية. انزل ببطء وكرر.', 1, 7, '/videos/81d785ab-96f4-5f7d-88ba-48d0db3b85b0.mp4', now(), now(), false),
  ('54ae59df-96f9-54a1-bcf7-91caf555c229', 'Standing Hip Abduction', 3, 10, 10, 'Stand tall holding a wall or chair for balance. Keep the standing leg straight. Slowly lift one leg out to the side. Keep the toes pointing forward. Lower with control and repeat, then switch legs.', 'قف بشكل مستقيم ممسكاً بحائط أو كرسي للتوازن. حافظ على استقامة ساق الوقوف. ارفع ساقاً واحدة ببطء إلى الجانب. حافظ على توجيه الأصابع للأمام. أنزل بتحكم وكرر ثم بدّل.', 1, 5, '/videos/54ae59df-96f9-54a1-bcf7-91caf555c229.mp4', now(), now(), false),
  ('03ae59bc-b955-51d4-82ea-5989b09b273b', 'Standing Leg Abduction (same as before)', 3, 10, 10, 'Stand with feet together holding a support for balance. Keep both legs straight and toes forward. Slide one leg out to the side as far as comfortable. Return the leg back to center. Repeat then switch sides.', 'قف والقدمان معاً وأمسك دعامة للتوازن. حافظ على استقامة الساقين وأصابع القدم للأمام. اسحب ساقاً واحدة للجانب لأقصى مدى مريح. عد بالساق للمنتصف. كرر ثم بدّل الجانبين.', 1, 5, '/videos/03ae59bc-b955-51d4-82ea-5989b09b273b.mp4', now(), now(), false),
  ('59026d59-7633-56bc-94a0-4fd0e113ca59', 'Standing Quadriceps Stretch', 3, 10, 10, 'Stand tall holding a wall or chair for balance. Bend one knee and grab the ankle behind you. Pull the heel toward the buttock. Keep the knees close together and hips forward. Hold 20–30 seconds and switch sides.', 'قف بشكل مستقيم ممسكاً بحائط أو كرسي للتوازن. اثنِ ركبة واحدة وأمسك الكاحل خلفك. اسحب الكعب نحو الأرداف. حافظ على الركبتين قريبتين والوركين للأمام. ثبّت 20–30 ثانية وبدّل.', 0, 6, '/videos/59026d59-7633-56bc-94a0-4fd0e113ca59.mp4', now(), now(), false),
  ('efa270a0-64d2-5a2f-b146-d4e6fcd66799', 'Standing Thoracic Rotation with Arm Sweep', 3, 10, 10, 'Stand with feet shoulder-width apart, arms extended forward. Rotate the trunk to one side, sweeping one arm behind. Follow the hand with your eyes. Return to center and rotate to the other side. Continue with a smooth flowing motion.', 'قف والقدمان بعرض الكتفين و الذراعين ممدودتان للأمام. أدر الجذع جهة مع كنس ذراع واحدة للخلف. اتبع اليد بالعينين. عد للوسط وأدر للجهة الأخرى. تابع بحركة سلسة متدفقة.', 1, 3, '/videos/efa270a0-64d2-5a2f-b146-d4e6fcd66799.mp4', now(), now(), false),
  ('22b154ce-1889-51fa-a0f5-953eed7612db', 'Straight Leg Raises', 3, 10, 10, 'Lie on your back with one leg bent and one straight. Tighten the thigh muscle of the straight leg. Slowly lift the straight leg to the height of the bent knee. Hold at the top for 10–5 seconds. Lower slowly and repeat, then switch legs.', 'استلقِ على ظهرك مع ثني ساق وفرد الأخرى. اشدّ عضلة الفخذ الساق المستقيمة. ارفع الساق المستقيمة ببطء ارتفاع الركبة المثنية. ثبّت في الأعلى لمدة 5–10 ثوانٍ. انزل ببطء وكرر ثم بدّل.', 1, 6, '/videos/22b154ce-1889-51fa-a0f5-953eed7612db.mp4', now(), now(), false),
  ('c6965352-0ea5-5c76-bcdc-d1c5265b1305', 'Superman', 3, 10, 10, 'Lie face down with arms extended overhead. Keep the legs straight and toes pointed. Lift the arms, chest, and legs off the floor at once. Hold the raised position for 8–5 seconds. Lower slowly and repeat.', 'استلقِ على البطن الذراعان ممدودتان فوق الرأس. حافظ على استقامة الساقين وأصابع القدم مشدودة. ارفع الذراعين والصدر والساقين عن الأرض معاً. ثبّت الوضع المرفوع لمدة 5–8 ثوانٍ. انزل ببطء وكرر.', 2, 4, '/videos/c6965352-0ea5-5c76-bcdc-d1c5265b1305.mp4', now(), now(), false),
  ('b734f354-14ea-597b-802c-a679cf7d20c4', 'Supine Active-Assisted Shoulder Flexion with Stick', 3, 10, 10, 'Lie on your back holding a stick with both hands. Rest the stick on your thighs to start. Use the healthy arm to push the stick overhead. Guide the affected arm through the range. Lower slowly and repeat.', 'استلقِ على ظهرك ممسكاً بعصا بكلتا اليدين. ضع العصا على الفخذين للبدء. استخدم الذراع السليمة لدفع العصا فوق الرأس. وجّه الذراع المصابة عبر النطاق. انزل ببطء وكرر.', 0, 0, '/videos/b734f354-14ea-597b-802c-a679cf7d20c4.mp4', now(), now(), false),
  ('16ffb9f6-9405-52b5-91ca-bcb67c51fe3b', 'Supine Active-Assisted Shoulder Flexion', 3, 10, 10, 'Lie on your back with arms at your sides. Use the healthy hand to grasp the affected wrist. Slowly lift the affected arm overhead with help. Move as far as comfortable without pain. Lower slowly and repeat.', 'استلقِ على ظهرك والذراعان بجانب الجسم. استخدم اليد السليمة لإمساك رسغ الذراع المصابة. ارفع الذراع المصابة فوق الرأس ببطء بمساعدة. تحرك لأقصى مدى مريح بدون ألم. أنزل ببطء وكرر.', 0, 0, '/videos/16ffb9f6-9405-52b5-91ca-bcb67c51fe3b.mp4', now(), now(), false),
  ('ed6146b3-53ec-5dd1-a8ae-d20c8d705988', 'Supine Arms Overhead Squeeze', 3, 10, 10, 'Lie on your back with arms extended overhead. Hold a soft ball between both hands. Squeeze the ball firmly for 5 seconds. Keep the arms straight throughout. Release and repeat.', 'استلقِ على ظهرك والذراعان ممدودتان فوق الرأس. أمسك كرة طرية بين اليدين. اضغط الكرة بقوة لمدة 5 ثوانٍ. حافظ على استقامة الذراعين طوال الحركة. استرخِ وكرر.', 0, 3, '/videos/ed6146b3-53ec-5dd1-a8ae-d20c8d705988.mp4', now(), now(), false),
  ('e81fe712-cd8a-5422-bdbd-e8b3f1fff290', 'Supine Elbow Flexion', 3, 10, 10, 'Lie on your back with the arm at your side. Hold a light dumbbell with palm facing up. Bend the elbow, curling the weight toward the shoulder. Keep the upper arm resting on the floor. Lower slowly and repeat.', 'استلقِ على ظهرك والذراع بجانب الجسم. أمسك دمبل خفيف و راحة اليد للأعلى. اثنِ الكوع ولفّ الوزن نحو الكتف. حافظ على الذراع العلوية على الأرض. انزل ببطء وكرر.', 0, 1, '/videos/e81fe712-cd8a-5422-bdbd-e8b3f1fff290.mp4', now(), now(), false),
  ('a7c06d4d-8483-54a6-9e85-49ac44596241', 'Supine Hamstring Stretch', 3, 10, 10, 'Lie on your back with one leg bent, foot flat. Loop a strap or towel around the other foot. Straighten the leg upward, pulling gently on the strap. Feel the stretch through the back of the thigh. Hold 20–30 seconds and switch legs.', 'استلقِ على ظهرك مع ثني ساق وقدمها على الأرض. لفّ شريطاً أو منشفة حول القدم الأخرى. افرد الساق للأعلى مع سحب الشريط بلطف. اشعر بالشد على خلفية الفخذ. ثبّت 20–30 ثانية وبدّل.', 0, 6, '/videos/a7c06d4d-8483-54a6-9e85-49ac44596241.mp4', now(), now(), false),
  ('8491ee0e-f1e5-5fd4-bab5-dadb7d0f4476', 'Supine Hip Flexor Stretch', 3, 10, 10, 'Lie on your back near the edge of a bench. Let one leg hang off the side toward the floor. Pull the other knee toward the chest. Feel a stretch across the front of the hanging hip. Hold 20–30 seconds and switch sides.', 'استلقِ على ظهرك قرب حافة مقعد. اترك ساقاً واحدة تتدلى من الجانب نحو الأرض. اسحب الركبة الأخرى نحو الصدر. اشعر بالشد على مقدمة الورك المتدلي. ثبّت 20–30 ثانية وبدّل.', 0, 5, '/videos/8491ee0e-f1e5-5fd4-bab5-dadb7d0f4476.mp4', now(), now(), false),
  ('d9366b38-9961-5148-bfaf-f4baa0802ca6', 'Supine Leg to Chest with Hip Internal Rotation', 3, 10, 10, 'Lie on your back and bring one knee toward the chest. Grasp the outside of the shin with both hands. Rotate the knee inward across the body. Feel a stretch deep in the outer hip. Hold 20–30 seconds and switch sides.', 'استلقِ على ظهرك وقرّب ركبة واحدة نحو الصدر. أمسك خارج الساق بكلتا اليدين. أدر الركبة للداخل عبر الجسم. اشعر بالشد العميق على خارج الورك. ثبّت 20–30 ثانية وبدّل.', 0, 5, '/videos/d9366b38-9961-5148-bfaf-f4baa0802ca6.mp4', now(), now(), false),
  ('711492c4-ad4a-51a7-9f69-81c5682f42fd', 'Supine Passive Shoulder Flexion with Stick', 3, 10, 10, 'Lie on your back holding a stick with both hands. Rest the stick on your thighs. Let the healthy arm slowly push the stick overhead. Allow the affected arm to be moved passively. Return to start and repeat.', 'استلقِ على ظهرك ممسكاً بعصا بكلتا اليدين. ضع العصا على الفخذين. دع الذراع السليمة تدفع العصا فوق الرأس ببطء. اسمح الذراع المصابة أن تتحرك بشكل منفعل. بعد البداية وكرر.', 0, 0, '/videos/711492c4-ad4a-51a7-9f69-81c5682f42fd.mp4', now(), now(), false),
  ('a217fa99-6619-5874-ab5b-a3923a526bd9', 'Supine Shoulder Flexion', 3, 10, 10, 'Lie on your back with arms at your sides. Keep the affected arm straight, palm facing up. Raise the arm slowly overhead toward the floor behind. Move as far as comfortable without pain. Lower slowly and repeat.', 'استلقِ على ظهرك و الذراعان بجانب الجسم. حافظ على استقامة الذراع المصابة وراحة اليد للأعلى. ارفع الذراع ببطء فوق الرأس نحو الأرض خلفك. تحرك لأقصى مدى مريح بدون ألم. انزل ببطء وكرر.', 0, 0, '/videos/a217fa99-6619-5874-ab5b-a3923a526bd9.mp4', now(), now(), false),
  ('fb4a580d-cab8-58e7-a569-834607cd91fc', 'Supine Single Leg Side Pull', 3, 10, 10, 'Lie on your back with legs straight. Bend one knee and cross it over the opposite leg. Use the opposite hand to pull the knee across. Keep the shoulders flat on the floor. Hold 20–30 seconds and switch sides.', 'استلقِ على ظهرك والساقان مستقيمتان. اثنِ ركبة واحدة وضعها فوق الساق المعاكسة. استخدم اليد المعاكسة لسحب الركبة عبر الجسم. حافظ على الكتفين مسطحين على الأرض. ثبّت 20–30 ثانية وبدّل.', 0, 3, '/videos/fb4a580d-cab8-58e7-a569-834607cd91fc.mp4', now(), now(), false),
  ('a5e79fdd-8fec-5619-b886-fec4acd0f0c8', 'Thoracic Foam Rolling', 3, 10, 10, 'Lie on your back with a foam roller under the upper back. Bend the knees with feet flat on the floor. Support the head with your hands. Slowly roll up and down the upper back. Pause on any tight spots for 15–20 seconds.', 'استلقِ على ظهرك واسطوانة فوق تحت أعلى الظهر. اثنِ الركبتين والقدمين على الأرض. ادعم الرأس بيديك. تدحرج ببطء لأعلى وأسفل أعلى الظهر. توقف على المناطق المشدودة لمدة 15–20 ثانية.', 0, 3, '/videos/a5e79fdd-8fec-5619-b886-fec4acd0f0c8.mp4', now(), now(), false),
  ('f22e79f3-e1bb-5188-874b-d749b46b5a0f', 'Thoracic Rotation Stretch with Arm Sweep', 3, 10, 10, 'Lie on your side with knees bent to 90 degrees stacked. Extend both arms straight in front at shoulder height. Slowly sweep the top arm across the body to the other side. Follow the hand with your eyes and let the trunk rotate. Return to start and repeat, then switch sides.', 'استلقِ على جانبك و ركبتان مثنيتان 90 درجة فوق بعضهما. فرد الذراعين مستقيمتين للأمام عند مستوى الكتف. اكنس الذراع العلوية عبر الجسم للجهة الأخرى ببطء. اتبع اليد بالعينين ودع الجذع يدور. بعد البداية وكرر ثم بدّل.', 0, 3, '/videos/f22e79f3-e1bb-5188-874b-d749b46b5a0f.mp4', now(), now(), false),
  ('daae50bc-107b-549f-ba42-1e4c9e379d9f', 'Towel Y Raises Lift-Off', 3, 10, 10, 'Lie face down holding a towel with both hands in a Y shape. Keep the arms straight and thumbs up. Lift the arms and towel off the floor. Squeeze the shoulder blades together. Lower slowly and repeat.', 'استلقِ على البطن ممسكاً بمنشفة بكلتا اليدين بشكل Y. حافظ على استقامة الذراعين و الإبهامين للأعلى. ارفع الذراعين والمنشفة عن الأرض. اضغط لوحي الكتف معاً. انزل ببطء وكرر.', 2, 0, '/videos/daae50bc-107b-549f-ba42-1e4c9e379d9f.mp4', now(), now(), false),
  ('95871689-32c2-513c-bb07-27e9a1603c4c', 'Thumb Flexion with Shoulder Flexion to 90 Degrees', 3, 10, 10, 'Stand or sit upright with the arm at your side. Raise the arm forward to 90 degrees, palm down. Bend the thumb across the palm. Hold the thumb position for 5–10 seconds. Release and lower the arm to repeat.', 'قف أو اجلس بشكل مستقيم والذراع بجانب الجسم. ارفع الذراع للأمام 90 درجة وراحة اليد للأسفل. اثنِ الإبهام عبر راحة اليد. ثبّت وضع الإبهام لمدة 5–10 ثوانٍ. استرخِ وأنزل الذراع للتكرار.', 1, 2, '/videos/95871689-32c2-513c-bb07-27e9a1603c4c.mp4', now(), now(), false),
  ('d9c390ce-f3be-5621-9cd0-323b9d7a1d93', 'Toe Touch', 3, 10, 10, 'Stand tall with feet hip-width apart. Keep the knees straight but not locked. Slowly hinge forward from the hips. Reach the fingers toward the toes. Hold 15–20 seconds then roll up slowly.', 'قف بشكل مستقيم والقدمين بعرض الوركين. حافظ على استقامة الركبتين دون فصلهما. انحنِ للأمام ببطء من الوركين. مدّ الأصابع نحو أصابع القدمين. ثبّت 15–20 ثانية ثم ارتفع ببطء.', 1, 7, '/videos/d9c390ce-f3be-5621-9cd0-323b9d7a1d93.mp4', now(), now(), false),
  ('0d702a15-2995-5ef9-8e34-367f8f514ffb', 'Ulnar Nerve Glide', 3, 10, 10, 'Stand with the arm at your side. Bend the elbow and rotate the forearm so the palm faces up. Bring the hand toward the face like an "OK" sign. Tilt the head away from the arm to add tension. Return to start and repeat smoothly.', 'قف والذراع بجانب الجسم. اثنِ الكوع وأدر الساعد حتى تصبح راحة اليد للأعلى. قرّب اليد من الوجه بإشارة "OK". أمل الرأس بعيداً عن الذراع لإضافة الشد. بعد البداية وكرر بسلاسة.', 0, 2, '/videos/0d702a15-2995-5ef9-8e34-367f8f514ffb.mp4', now(), now(), false),
  ('39dd2c51-362e-53d4-9e13-df7fcf8fd416', 'Wall Calf Stretch', 3, 10, 10, 'Stand facing a wall with hands at shoulder height. Step one foot back keeping it flat on the floor. Bend the front knee and lean into the wall. Feel a stretch in the back leg calf. Hold 20–30 seconds and switch sides.', 'قف مواجهاً حائطاً واليدان على مستوى الكتف. اخطُ قدماً واحدة للخلف وحافظ عليها مسطحة. اثنِ الركبة الأمامية ومل نحو الحائط. اشعر بالشد في بطة الساق الخلفية. ثبّت 20–30 ثانية وبدّل.', 0, 7, '/videos/39dd2c51-362e-53d4-9e13-df7fcf8fd416.mp4', now(), now(), false),
  ('4e315906-9cbd-5572-9dd2-7c40dc3ac6f2', 'Wall Finger Walk', 3, 10, 10, 'Stand facing a wall at arm''s length. Place the fingertips on the wall at shoulder height. Walk the fingers up the wall as high as comfortable. Move only the fingers, keeping shoulders relaxed. Walk back down slowly and repeat.', 'قف مواجهاً حائطاً على مسافة ذراع. ضع أطراف الأصابع على الحائط عند مستوى الكتف. امشِ بالإصبع لأعلى الحائط لأقصى ارتفاع مريح. حرّك الأصابع فقط مع استرخاء الكتفين. امشِ لأسفل ببطء وكرر.', 1, 2, '/videos/4e315906-9cbd-5572-9dd2-7c40dc3ac6f2.mp4', now(), now(), false),
  ('594d36c1-adba-5ef1-8eeb-dd86fec201e4', 'Wall Posture', 3, 10, 10, 'Stand with your back against a wall. Press the head, upper back, and buttocks into the wall. Bring the arms up in a goalpost position. Keep the back of the hands touching the wall. Hold 15–30 seconds while breathing calmly.', 'قف وظهرك ملاصق للحائط. اضغط الرأس وأعلى الظهر والأرداف على الحائط. ارفع الذراعين بوضع المرمى. حافظ على تلامس ظهر اليدين مع الحائط. ثبّت 15–30 ثانية مع التنفس الهادئ.', 0, 3, '/videos/594d36c1-adba-5ef1-8eeb-dd86fec201e4.mp4', now(), now(), false),
  ('70db9d53-92bc-51dd-b2fd-78e3cf7dc0f9', 'Wall Sit', 3, 10, 10, 'Stand with your back against a wall. Slide down until your knees are bent to 90 degrees. Keep the feet shoulder-width apart, flat on the floor. Press the lower back into the wall. Hold as long as possible with good form.', 'قف وظهرك ملاصق للحائط. اسحب لأسفل حتى تصبح الركبتين بزاوية 90 درجة. حافظ على القدمين بعرض الكتفين على الأرض. اضغط أسفل الظهر على الحائط. ثبّت لأطول فترة ممكنة مع الحفاظ على الوضع.', 1, 6, '/videos/70db9d53-92bc-51dd-b2fd-78e3cf7dc0f9.mp4', now(), now(), false),
  ('5957e269-aa12-5a45-96cd-4407138bd2e5', 'Wall Squats', 3, 10, 10, 'Stand with your back against a wall, feet slightly forward. Slide down the wall into a squat position. Stop when the knees reach 90 degrees. Push through the heels to slide back up. Repeat with a controlled tempo.', 'قف وظهرك على الحائط والقدمان للأمام قليلاً. اسحب لأسفل على الحائط لوضع السكوات. توقف عندما تصل الركبتين لـ 90 درجة. ادفع من الكعبين العودة للأعلى. كرر بإيقاع متحكم به.', 1, 6, '/videos/5957e269-aa12-5a45-96cd-4407138bd2e5.mp4', now(), now(), false),
  ('c54ea9b1-2023-5554-8145-f950f6224c7b', 'Wall Stretch', 3, 10, 10, 'Stand facing a wall with feet hip-width apart. Place both palms on the wall at shoulder height. Step back and hinge forward from the hips. Let the chest drop between the arms. Hold 20–30 seconds and release.', 'قف مواجهاً حائطاً والقدمان بعرض الوركين. ضع راحتي اليدين على الحائط بمستوى الكتف. اخطُ للخلف وانحنِ للأمام من الوركين. اترك الصدر ينزل بين الذراعين. ثبّت 20–30 ثانية واسترخِ.', 0, 3, '/videos/c54ea9b1-2023-5554-8145-f950f6224c7b.mp4', now(), now(), false),
  ('26c47ca7-65c7-5ba6-952f-49fdf4ffca2c', 'Weighted Finger Flexion', 3, 10, 10, 'Sit with the forearm resting on a table, palm up. Place a light weight in the palm of the hand. Curl the fingers to lift the weight. Hold at the top for 2–3 seconds. Lower slowly and repeat.', 'اجلس والساعد مستند على طاولة وراحة اليد للأعلى. ضع وزناً خفيفاً في راحة اليد. لفّ الأصابع لرفع الوزن. ثبّت في الأعلى لمدة 2–3 ثوانٍ. انزل ببطء وكرر.', 1, 2, '/videos/26c47ca7-65c7-5ba6-952f-49fdf4ffca2c.mp4', now(), now(), false),
  ('3a6daea9-9f20-53fe-aadd-9f202e7eb094', 'Wrist Extension Stretch', 3, 10, 10, 'Extend the affected arm in front, palm facing down. Use the other hand to gently pull the fingers upward. Feel a stretch on the underside of the forearm. Keep the elbow straight throughout. Hold 20–30 seconds and release.', 'مدّ الذراع المصابة للأمام وراحة اليد للأسفل. استخدم اليد الأخرى لسحب الأصابع للأعلى بلطف. اشعر بالشد على الجانب السفلي للساعد. حافظ على استقامة الكوع طول الحركة. ثبّت 20–30 ثانية واسترخِ.', 0, 2, '/videos/3a6daea9-9f20-53fe-aadd-9f202e7eb094.mp4', now(), now(), false),
  ('15badad2-ebfd-5947-85e2-86af0232088e', 'Wrist Flexion Stretch', 3, 10, 10, 'Extend the affected arm in front, palm facing up. Use the other hand to gently pull the fingers downward. Feel a stretch on the top of the forearm. Keep the elbow straight throughout. Hold 20–30 seconds and release.', 'مدّ الذراع المصابة للأمام وراحة اليد للأعلى. استخدم اليد الأخرى لسحب الأصابع للأسفل بلطف. اشعر بالشد على السطح العلوي للساعد. حافظ على استقامة الكوع طول الحركة. ثبّت 20–30 ثانية واسترخِ.', 0, 2, '/videos/15badad2-ebfd-5947-85e2-86af0232088e.mp4', now(), now(), false),
  ('0253640e-955a-555f-bdbb-a838b5e4f655', 'Wrist Radial Deviation', 3, 10, 10, 'Rest the forearm on a table with your thumb pointing up. Keep the hand relaxed off the edge of the table. Slowly bend the wrist upward toward the thumb. Hold at the top for 2–3 seconds. Return slowly and repeat.', 'ضع الساعد على طاولة والإبهام للأعلى. حافظ على استرخاء اليد خارج حافة الطاولة. اثنِ الرسغ ببطء للأعلى نحو الإبهام. ثبّت في الأعلى لمدة 2–3 ثوانٍ. عد ببطء وكرر.', 1, 2, '/videos/0253640e-955a-555f-bdbb-a838b5e4f655.mp4', now(), now(), false),
  ('0cee4315-1b86-5903-90f2-f962fd91ba66', 'Wrist Rolls', 3, 10, 10, 'Extend both arms in front of you at shoulder height. Make loose fists with both hands. Slowly rotate the wrists in a full circle. Complete rolls in one direction. Reverse direction and repeat.', 'فرد الذراعين للأمام عند مستوى الكتف. كوّن قبضتين مرتخيتين باليدين. أدر الرسغين بدائرة كاملة ببطء. أكمل دورات باتجاه واحد. اعكس الاتجاه وكرر.', 0, 2, '/videos/0cee4315-1b86-5903-90f2-f962fd91ba66.mp4', now(), now(), false),
  ('42df636a-2acf-5737-9ae2-ce9d0771112a', 'Wrist Side to Side', 3, 10, 10, 'Rest the forearm on a table, palm down. Keep the hand relaxed off the edge of the table. Slowly move the wrist side to side. Cover the full comfortable range. Return to neutral and repeat.', 'ضع الساعد على طاولة وراحة اليد للأسفل. حافظ على استرخاء اليد خارج حافة الطاولة. حرّك الرسغ ببطء من جانب لآخر. غطِّ النطاق الكامل المريح. عد إلى الوضع المحايد وكرر.', 1, 2, '/videos/42df636a-2acf-5737-9ae2-ce9d0771112a.mp4', now(), now(), false),
  ('30f7fa9d-58c1-5645-80f8-5dbe2fab1b14', 'Wrist Ulnar Deviation', 3, 10, 10, 'Rest the forearm on a table with your thumb pointing up. Keep the hand relaxed off the edge of the table. Slowly bend the wrist downward toward the pinky. Hold at the end range for 2–3 seconds. Return slowly and repeat.', 'ضع الساعد على طاولة والإبهام للأعلى. حافظ على استرخاء اليد خارج حافة الطاولة. اثنِ الرسغ ببطء للأسفل نحو الخنصر. ثبّت في نهاية الحركة لمدة 2–3 ثوانٍ. عد ببطء وكرر.', 1, 2, '/videos/30f7fa9d-58c1-5645-80f8-5dbe2fab1b14.mp4', now(), now(), false)
